# -*- coding: utf-8 -*-
import pytest

from taf.playwright.sbts.common.exceptions import SessionNotFound
from taf.playwright.sbts.common.session_store import SessionStore


class DummySession(object):
    def __init__(self):
        self.closed = False

    def close(self):
        self.closed = True


def test_session_store_adds_and_gets_default_session():
    store = SessionStore()
    session = DummySession()

    store.add(session)

    assert store.get() is session
    assert store.aliases() == [None]


def test_session_store_adds_and_removes_named_session():
    store = SessionStore()
    session = DummySession()

    store.add(session, alias="sbts1")
    removed = store.remove("sbts1")

    assert removed is session
    with pytest.raises(SessionNotFound):
        store.get("sbts1")


def test_session_store_close_all_closes_sessions():
    store = SessionStore()
    session1 = DummySession()
    session2 = DummySession()
    store.add(session1, alias="sbts1")
    store.add(session2, alias="sbts2")

    store.close_all()

    assert session1.closed is True
    assert session2.closed is True
    assert store.aliases() == []
